import{bQ as e,aL as t,u as r,G as s}from"./chunks/framework.DpUpLuct.js";const u=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/intro.md","filePath":"guide/intro.md","lastUpdated":1790485184000}'),n={name:"guide/intro.md"};function l(i,a,o,d,p,c){return t(),r("div",null,[...a[0]||(a[0]=[s(`<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><p><code>gh-proxy</code> 是一个用于加速 GitHub 资源下载的中间层服务。它把 GitHub 上常用的下载链接，通过部署在 Cloudflare Workers 上的代理服务转发出去，从而获得更稳定、更快速的下载体验。</p><p>它特别适合以下场景：</p><ul><li>下载 release 发布包、archive 源码包时速度缓慢；</li><li>拉取 <code>raw.githubusercontent.com</code>、<code>gist.githubusercontent.com</code> 上的文件；</li><li>使用 <code>git clone</code> 拉取较大的仓库；</li><li>不想安装任何客户端，只想在链接前加一个域名即可加速。</li></ul><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>边缘加速</td><td>基于 Cloudflare Workers，请求就近接入，全球访问更快</td></tr><tr><td>全格式支持</td><td>release、archive、blob/raw 文件、gist、tags 等均支持</td></tr><tr><td>支持 Clone</td><td>在仓库地址前加加速域名即可加速 <code>git clone</code></td></tr><tr><td>免登录</td><td>公开资源无需任何账号即可下载</td></tr><tr><td>双版本</td><td>提供 Cloudflare Workers 与 Python（Flask）两种部署方式</td></tr><tr><td>可自定义</td><td>支持白名单、黑名单、jsDelivr 镜像、文件大小限制等配置</td></tr></tbody></table><h2 id="两个版本的差异" tabindex="-1">两个版本的差异 <a class="header-anchor" href="#两个版本的差异" aria-label="Permalink to &quot;两个版本的差异&quot;">​</a></h2><p>项目同时提供 Cloudflare Workers 版本（<code>index.js</code>）与 Python 版本（<code>app/main.py</code>），两者能力基本一致：</p><ul><li><strong>Cloudflare Workers 版本</strong>：免服务器，部署简单，适合个人和小规模使用，免费额度为每天 10 万次请求。</li><li><strong>Python 版本</strong>：可自行托管在服务器上，支持文件大小限制、特定 <code>user/repo</code> 的封禁/白名单以及 passby 等更细粒度的控制。</li></ul><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 / git</span></span>
<span class="line"><span>      │  请求 https://加速域名/&lt;GitHub 原始链接&gt;</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>gh-proxy 服务（Cloudflare Worker 或 Python 服务）</span></span>
<span class="line"><span>      │  识别链接类型后转发请求</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>GitHub（release / archive / raw / gist ...）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>当访问的路径不是一个可识别的 GitHub 链接时，服务会把它当作静态资源，回落到配置好的 <code>ASSET_URL</code>（也就是本网站），因此本站既是在线工具页，也是服务的主页。</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li>上游项目：<a href="https://github.com/hunshcn/gh-proxy" target="_blank" rel="noreferrer">hunshcn/gh-proxy</a></li><li>本项目仓库：<a href="https://github.com/MinimaxFlora/gh-proxy" target="_blank" rel="noreferrer">MinimaxFlora/gh-proxy</a></li><li>参考实现：<a href="https://github.com/EtherDream/jsproxy/" target="_blank" rel="noreferrer">jsproxy</a></li></ul>`,14)])])}const b=e(n,[["render",l]]);export{u as __pageData,b as default};
